// NoobToRoot : banque de questions
// Regénérable depuis Google Sheets / Excel avec csv_vers_data.py
// Champs : id, lang, d (difficulté 1-3), q, a (réponses ; "re:" = regex), x (2 leurres), h (indice), e (explication)
window.NTR_QUESTIONS = [
// ───────── SHELL ─────────
{"id": "SH-01", "lang": "shell", "d": 1, "q": "Afficher la liste des fichiers du dossier courant", "a": ["ls"], "x": ["cd", "pwd"], "h": "Deux lettres : l'abréviation de « list »", "e": "`ls` liste le contenu du dossier où tu te trouves. Ajoute `-la` pour voir aussi les fichiers cachés."},
{"id": "SH-02", "lang": "shell", "d": 1, "q": "Afficher le chemin complet du dossier où tu te trouves", "a": ["pwd"], "x": ["ls", "whoami"], "h": "print working directory", "e": "`pwd` affiche le chemin absolu du dossier courant, par exemple /home/charlotte."},
{"id": "SH-03", "lang": "shell", "d": 1, "q": "Entrer dans le dossier Documents", "a": ["cd Documents", "cd Documents/", "cd ./Documents"], "x": ["ls Documents", "mv Documents"], "h": "change directory", "e": "`cd` (change directory) te déplace dans un autre dossier."},
{"id": "SH-04", "lang": "shell", "d": 1, "q": "Remonter au dossier parent", "a": ["cd .."], "x": ["cd ~", "cd /"], "h": "Deux points désignent le dossier du dessus", "e": "`..` désigne le dossier parent. `cd ~` ramène au dossier personnel, `cd /` à la racine."},
{"id": "SH-05", "lang": "shell", "d": 1, "q": "Créer un dossier nommé projet", "a": ["mkdir projet"], "x": ["touch projet", "cd projet"], "h": "make directory", "e": "`mkdir` (make directory) crée un nouveau dossier."},
{"id": "SH-06", "lang": "shell", "d": 1, "q": "Créer un fichier vide nommé notes.txt", "a": ["touch notes.txt", "> notes.txt"], "x": ["mkdir notes.txt", "cat notes.txt"], "h": "Commande qui « touche » un fichier", "e": "`touch` crée un fichier vide s'il n'existe pas, ou met à jour sa date de modification."},
{"id": "SH-07", "lang": "shell", "d": 1, "q": "Afficher le contenu du fichier notes.txt", "a": ["cat notes.txt"], "x": ["ls notes.txt", "touch notes.txt"], "h": "Comme un chat, mais pour concaténer", "e": "`cat` (concatenate) affiche le contenu d'un ou plusieurs fichiers."},
{"id": "SH-08", "lang": "shell", "d": 1, "q": "Effacer l'écran du terminal", "a": ["clear"], "x": ["exit", "rm"], "h": "En anglais : vider, dégager", "e": "`clear` nettoie l'écran. Raccourci clavier équivalent : Ctrl + L."},
{"id": "SH-22", "lang": "shell", "d": 1, "q": "Afficher la date et l'heure actuelles", "a": ["date"], "x": ["time", "now"], "h": "Le mot anglais, tout simplement", "e": "`date` affiche la date et l'heure du système. `date +%H:%M` n'affiche que l'heure."},
{"id": "SH-23", "lang": "shell", "d": 1, "q": "Afficher le texte Bonjour dans le terminal", "a": ["echo Bonjour", "echo \"Bonjour\""], "x": ["print Bonjour", "say Bonjour"], "h": "Le terminal te renvoie l'écho", "e": "`echo` affiche le texte qu'on lui donne. Très utile dans les scripts pour afficher des messages."},
{"id": "SH-24", "lang": "shell", "d": 1, "q": "Revenir directement à ton dossier personnel", "a": ["cd", "cd ~", "cd $HOME"], "x": ["cd /", "cd .."], "h": "cd tout seul, ou avec le tilde", "e": "`cd` sans argument ou `cd ~` ramène au dossier personnel. `/` est la racine du système, `..` le dossier parent."},
{"id": "SH-25", "lang": "shell", "d": 1, "q": "Afficher le manuel de la commande ls", "a": ["man ls"], "x": ["doc ls", "ls --manual"], "h": "Abréviation de manual", "e": "`man commande` ouvre la documentation complète. On en sort avec la touche q."},
{"id": "SH-26", "lang": "shell", "d": 1, "q": "Quitter le terminal", "a": ["exit", "logout"], "x": ["quit", "close"], "h": "Sortir, en anglais", "e": "`exit` ferme la session du terminal. Raccourci clavier équivalent : Ctrl + D."},
{"id": "SH-27", "lang": "shell", "d": 1, "q": "Afficher l'historique des commandes déjà tapées", "a": ["history"], "x": ["log", "last"], "h": "Le mot anglais pour histoire", "e": "`history` liste les commandes précédentes, numérotées. `!42` relance la commande numéro 42."},
{"id": "SH-28", "lang": "shell", "d": 1, "q": "Lister le contenu du dossier /etc sans t'y déplacer", "a": ["ls /etc", "ls /etc/"], "x": ["cd /etc", "cat /etc"], "h": "ls accepte un chemin après lui", "e": "`ls chemin` liste un autre dossier sans quitter celui où tu es. /etc contient les fichiers de configuration du système."},
{"id": "SH-29", "lang": "shell", "d": 1, "q": "Créer deux dossiers a et b en une seule commande", "a": ["mkdir a b", "mkdir b a"], "x": ["mkdir a,b", "touch a b"], "h": "Une seule commande, deux noms séparés par un espace", "e": "La plupart des commandes acceptent plusieurs arguments séparés par des espaces : `mkdir a b` crée les deux dossiers."},
{"id": "SH-30", "lang": "shell", "d": 1, "q": "Afficher le calendrier du mois en cours", "a": ["cal", "ncal"], "x": ["month", "date --cal"], "h": "Trois lettres, abréviation de calendar", "e": "`cal` affiche le mois en cours. `cal 2026` affiche toute l'année."},
{"id": "SH-31", "lang": "shell", "d": 1, "q": "Afficher depuis combien de temps l'ordinateur est allumé", "a": ["uptime"], "x": ["date", "time"], "h": "« Temps en marche », en anglais", "e": "`uptime` donne la durée depuis le démarrage, le nombre d'utilisateurs et la charge du système."},
{"id": "SH-32", "lang": "shell", "d": 1, "q": "Supprimer le dossier vide temp", "a": ["rmdir temp", "rm -d temp", "rm -r temp", "rm -rf temp"], "x": ["rm temp", "del temp"], "h": "remove directory", "e": "`rmdir` supprime un dossier vide. `rm` seul refuse de supprimer un dossier."},
{"id": "SH-33", "lang": "shell", "d": 1, "q": "Lire le fichier notes.txt page par page", "a": ["less notes.txt", "more notes.txt"], "x": ["cat -p notes.txt", "page notes.txt"], "h": "Moins… ou plus", "e": "`less` permet de défiler avec les flèches et de chercher avec /. On quitte avec q."},
{"id": "SH-09", "lang": "shell", "d": 2, "q": "Lister tous les fichiers, y compris cachés, en format détaillé", "a": ["ls -la", "ls -al", "ls -l -a", "ls -a -l"], "x": ["ls -h", "ls -r"], "h": "-l pour détaillé, -a pour all", "e": "`-l` affiche droits, taille et date ; `-a` montre les fichiers cachés (ceux qui commencent par un point)."},
{"id": "SH-10", "lang": "shell", "d": 2, "q": "Copier notes.txt vers sauvegarde.txt", "a": ["cp notes.txt sauvegarde.txt"], "x": ["mv notes.txt sauvegarde.txt", "cat notes.txt sauvegarde.txt"], "h": "copy, en deux lettres", "e": "`cp source destination` copie un fichier. L'original reste en place."},
{"id": "SH-11", "lang": "shell", "d": 2, "q": "Renommer brouillon.txt en final.txt", "a": ["mv brouillon.txt final.txt"], "x": ["cp brouillon.txt final.txt", "rn brouillon.txt final.txt"], "h": "Sous Linux, renommer c'est déplacer", "e": "`mv` (move) déplace ou renomme. Il n'y a pas de commande « rename » de base."},
{"id": "SH-12", "lang": "shell", "d": 2, "q": "Supprimer le fichier vieux.txt", "a": ["rm vieux.txt"], "x": ["rmdir vieux.txt", "del vieux.txt"], "h": "remove", "e": "`rm` supprime définitivement : pas de corbeille dans le terminal."},
{"id": "SH-13", "lang": "shell", "d": 2, "q": "Afficher le nom de l'utilisateur connecté", "a": ["whoami"], "x": ["pwd", "hostname"], "h": "Pose la question en anglais, en un seul mot", "e": "`whoami` (who am I) affiche ton nom d'utilisateur. Très utilisé en pentest pour savoir avec quels droits on agit."},
{"id": "SH-14", "lang": "shell", "d": 2, "q": "Chercher les lignes contenant le mot erreur dans log.txt", "a": ["grep erreur log.txt", "grep \"erreur\" log.txt"], "x": ["find erreur log.txt", "cat erreur log.txt"], "h": "Quatre lettres, l'outil de recherche de texte", "e": "`grep motif fichier` affiche les lignes qui contiennent le motif. `-i` ignore la casse."},
{"id": "SH-15", "lang": "shell", "d": 2, "q": "Afficher les 10 premières lignes de log.txt", "a": ["head log.txt", "head -n 10 log.txt", "head -10 log.txt"], "x": ["tail log.txt", "less log.txt"], "h": "La tête du fichier", "e": "`head` montre le début (10 lignes par défaut), `tail` la fin."},
{"id": "SH-34", "lang": "shell", "d": 2, "q": "Afficher les 10 dernières lignes de log.txt", "a": ["tail log.txt", "tail -n 10 log.txt", "tail -10 log.txt"], "x": ["head log.txt", "end log.txt"], "h": "La queue du fichier", "e": "`tail` affiche la fin d'un fichier. `tail -f log.txt` suit le fichier en direct, pratique pour surveiller des journaux."},
{"id": "SH-35", "lang": "shell", "d": 2, "q": "Copier le dossier photos et tout son contenu vers sauvegarde", "a": ["cp -r photos sauvegarde", "cp -R photos sauvegarde", "cp -a photos sauvegarde"], "x": ["cp photos sauvegarde", "mv -r photos sauvegarde"], "h": "cp, en mode récursif", "e": "Sans `-r`, `cp` refuse de copier un dossier. `-a` copie aussi les droits et les dates."},
{"id": "SH-36", "lang": "shell", "d": 2, "q": "Chercher erreur dans log.txt sans tenir compte des majuscules", "a": ["grep -i erreur log.txt", "grep -i \"erreur\" log.txt"], "x": ["grep erreur log.txt", "grep -v erreur log.txt"], "h": "Une option qui ignore la casse", "e": "`-i` ignore la casse : Erreur, ERREUR et erreur sont trouvés. `-v` fait l'inverse : il affiche les lignes qui ne contiennent pas le motif."},
{"id": "SH-37", "lang": "shell", "d": 2, "q": "Ajouter la ligne fin à la fin de notes.txt avec echo", "a": ["echo fin >> notes.txt", "echo \"fin\" >> notes.txt"], "x": ["echo fin > notes.txt", "echo fin | notes.txt"], "h": "Deux chevrons pour ajouter", "e": "`>>` ajoute à la fin du fichier. Avec un seul `>`, tout le contenu existant serait effacé."},
{"id": "SH-38", "lang": "shell", "d": 2, "q": "Afficher l'espace disque disponible, lisible par un humain", "a": ["df -h"], "x": ["du -h", "free -h"], "h": "disk free, option humaine", "e": "`df -h` affiche l'espace libre de chaque disque en Go ou Mo. `du` mesure la taille des dossiers, `free` la mémoire vive."},
{"id": "SH-39", "lang": "shell", "d": 2, "q": "Afficher la taille totale du dossier photos, lisible par un humain", "a": ["du -sh photos", "du -hs photos", "du -sh photos/"], "x": ["df -h photos", "ls -s photos"], "h": "disk usage, en résumé", "e": "`du -sh` donne un total (`-s` pour summary) en unités lisibles (`-h`)."},
{"id": "SH-40", "lang": "shell", "d": 2, "q": "Afficher la mémoire vive libre, lisible par un humain", "a": ["free -h"], "x": ["df -h", "mem -h"], "h": "« Libre », en anglais", "e": "`free -h` affiche la RAM totale, utilisée et disponible."},
{"id": "SH-41", "lang": "shell", "d": 2, "q": "Afficher les processus en temps réel, comme un gestionnaire de tâches", "a": ["top", "htop"], "x": ["ps", "jobs"], "h": "Le sommet de la liste", "e": "`top` se met à jour en continu et classe les processus par consommation. `htop` en est une version plus confortable. On quitte avec q."},
{"id": "SH-42", "lang": "shell", "d": 2, "q": "Afficher le chemin de l'exécutable python3", "a": ["which python3", "type python3", "command -v python3"], "x": ["where python3", "find python3"], "h": "Lequel ? en anglais", "e": "`which` indique quel fichier est lancé quand tu tapes une commande. Pratique quand plusieurs versions coexistent."},
{"id": "SH-43", "lang": "shell", "d": 2, "q": "Créer un lien symbolique nommé raccourci qui pointe vers /var/log", "a": ["ln -s /var/log raccourci"], "x": ["ln /var/log raccourci", "link -s raccourci /var/log"], "h": "ln, option s, cible d'abord", "e": "`ln -s cible nom` crée un raccourci. L'ordre est toujours : ce qui existe, puis le nouveau nom."},
{"id": "SH-44", "lang": "shell", "d": 2, "q": "Trier les lignes de noms.txt par ordre alphabétique", "a": ["sort noms.txt"], "x": ["order noms.txt", "sort -r noms.txt"], "h": "Trier, en anglais", "e": "`sort` trie les lignes. `-r` inverse l'ordre, `-n` trie des nombres."},
{"id": "SH-45", "lang": "shell", "d": 2, "q": "Afficher noms.txt trié et sans doublons", "a": ["sort -u noms.txt", "sort noms.txt | uniq"], "x": ["uniq -d noms.txt", "sort -r noms.txt"], "h": "sort, avec une option unique", "e": "`sort -u` trie et retire les doublons. `uniq` seul ne retire que les doublons consécutifs, d'où le tri avant."},
{"id": "SH-46", "lang": "shell", "d": 2, "q": "Afficher le nom de la machine", "a": ["hostname"], "x": ["whoami", "uname"], "h": "Le nom de l'hôte", "e": "`hostname` affiche le nom de l'ordinateur sur le réseau. `whoami` donne l'utilisateur, `uname` le système."},
{"id": "SH-16", "lang": "shell", "d": 3, "q": "Supprimer le dossier archives et tout son contenu", "a": ["rm -r archives", "rm -rf archives", "rm -fr archives", "rm -R archives"], "x": ["rmdir archives", "rm archives"], "h": "rm, en mode récursif", "e": "`-r` supprime récursivement. `rmdir` ne marche que sur un dossier vide. Avec `-f`, aucune confirmation : prudence."},
{"id": "SH-17", "lang": "shell", "d": 3, "q": "Rendre le fichier script.sh exécutable", "a": ["chmod +x script.sh", "chmod u+x script.sh", "chmod a+x script.sh"], "x": ["chown +x script.sh", "run script.sh"], "h": "change mode, et le droit x", "e": "`chmod +x` ajoute le droit d'exécution. On lance ensuite le script avec `./script.sh`."},
{"id": "SH-18", "lang": "shell", "d": 3, "q": "Trouver tous les fichiers .txt dans le dossier courant et ses sous-dossiers", "a": ["find . -name \"*.txt\"", "find . -name *.txt", "find . -iname \"*.txt\""], "x": ["grep *.txt .", "ls *.txt"], "h": "find, puis le point de départ, puis -name", "e": "`find . -name \"*.txt\"` parcourt toute l'arborescence. Les guillemets empêchent le shell d'interpréter l'étoile trop tôt."},
{"id": "SH-19", "lang": "shell", "d": 3, "q": "Compter le nombre de lignes de log.txt", "a": ["wc -l log.txt", "wc -l < log.txt", "cat log.txt | wc -l"], "x": ["count log.txt", "cat -n log.txt"], "h": "word count, option lignes", "e": "`wc` (word count) compte lignes, mots et caractères. `-l` ne garde que les lignes."},
{"id": "SH-20", "lang": "shell", "d": 3, "q": "Lister tous les processus de tous les utilisateurs", "a": ["ps aux", "ps -ef", "ps -aux", "ps -e"], "x": ["ps", "jobs"], "h": "process status, avec des options", "e": "`ps aux` (style BSD) ou `ps -ef` (style Unix) listent tous les processus. `ps` seul ne montre que ceux de ton terminal."},
{"id": "SH-21", "lang": "shell", "d": 3, "q": "Écrire la sortie de ls dans fichiers.txt, en écrasant son contenu", "a": ["ls > fichiers.txt"], "x": ["ls >> fichiers.txt", "ls | fichiers.txt"], "h": "Une redirection, un seul chevron", "e": "`>` écrase le fichier, `>>` ajoute à la fin. `|` envoie la sortie vers une autre commande, pas vers un fichier."},
{"id": "SH-47", "lang": "shell", "d": 3, "q": "Compter les fichiers du dossier courant en combinant deux commandes", "a": ["ls | wc -l", "ls -1 | wc -l"], "x": ["ls -c", "count ls"], "h": "ls, un tube, et le compteur de lignes", "e": "Le tube `|` envoie la sortie de `ls` à `wc -l`, qui compte les lignes. Combiner de petites commandes, c'est tout l'esprit du shell."},
{"id": "SH-48", "lang": "shell", "d": 3, "q": "Donner rwx au propriétaire et r-x au groupe et aux autres sur script.sh, en octal", "a": ["chmod 755 script.sh"], "x": ["chmod 777 script.sh", "chmod 644 script.sh"], "h": "r=4, w=2, x=1 : additionne pour chaque groupe", "e": "7 = 4+2+1 (rwx), 5 = 4+1 (r-x). `777` donnerait l'écriture à tout le monde : une faille classique."},
{"id": "SH-49", "lang": "shell", "d": 3, "q": "Donner le fichier site.html à l'utilisateur charlotte", "a": ["chown charlotte site.html", "sudo chown charlotte site.html"], "x": ["chmod charlotte site.html", "chgrp charlotte site.html"], "h": "change owner", "e": "`chown` change le propriétaire. `chmod` change les droits, `chgrp` le groupe."},
{"id": "SH-50", "lang": "shell", "d": 3, "q": "Lancer apt update avec les droits administrateur", "a": ["sudo apt update"], "x": ["su apt update", "root apt update"], "h": "super user do", "e": "`sudo` exécute une seule commande en administrateur, après ton mot de passe. `su` change d'utilisateur pour toute la session."},
{"id": "SH-51", "lang": "shell", "d": 3, "q": "Arrêter le processus numéro 1234", "a": ["kill 1234", "kill -15 1234", "kill -9 1234", "kill -TERM 1234", "kill -KILL 1234"], "x": ["stop 1234", "ps -k 1234"], "h": "Le nom est explicite…", "e": "`kill` envoie un signal au processus. Par défaut il demande poliment l'arrêt (15) ; `-9` force l'arrêt immédiat."},
{"id": "SH-52", "lang": "shell", "d": 3, "q": "Archiver et compresser le dossier projet dans projet.tar.gz", "a": ["tar -czf projet.tar.gz projet", "tar czf projet.tar.gz projet", "tar -zcf projet.tar.gz projet", "tar -czvf projet.tar.gz projet", "tar -cvzf projet.tar.gz projet", "tar -zcvf projet.tar.gz projet"], "x": ["zip projet.tar.gz projet", "tar -xzf projet.tar.gz projet"], "h": "tar avec c (create), z (gzip), f (file)", "e": "`c` crée, `z` compresse en gzip, `f` désigne le fichier d'archive, qui vient juste après."},
{"id": "SH-53", "lang": "shell", "d": 3, "q": "Extraire l'archive projet.tar.gz", "a": ["tar -xzf projet.tar.gz", "tar xzf projet.tar.gz", "tar -xf projet.tar.gz", "tar -xvzf projet.tar.gz", "tar -zxf projet.tar.gz", "tar -zxvf projet.tar.gz"], "x": ["tar -czf projet.tar.gz", "unzip projet.tar.gz"], "h": "tar avec x pour extract", "e": "`x` extrait. Les versions récentes de tar devinent la compression : `tar -xf` suffit souvent."},
{"id": "SH-54", "lang": "shell", "d": 3, "q": "Télécharger https://example.com/f.txt avec wget", "a": ["wget https://example.com/f.txt"], "x": ["download https://example.com/f.txt", "get https://example.com/f.txt"], "h": "La commande, puis l'adresse", "e": "`wget` télécharge un fichier dans le dossier courant. `curl -O` fait la même chose."},
{"id": "SH-55", "lang": "shell", "d": 3, "q": "Afficher le contenu de la variable PATH", "a": ["echo $PATH", "echo \"$PATH\""], "x": ["echo PATH", "cat $PATH"], "h": "echo, et le signe dollar devant le nom", "e": "Le `$` lit la valeur d'une variable. PATH liste les dossiers où le shell cherche les commandes."},
{"id": "SH-56", "lang": "shell", "d": 3, "q": "Créer une variable NOM qui vaut Ada", "a": ["NOM=Ada", "NOM=\"Ada\""], "x": ["NOM = Ada", "set NOM Ada"], "h": "Attention : aucun espace", "e": "En shell, pas d'espace autour du `=` : `NOM = Ada` lancerait une commande nommée NOM."},
{"id": "SH-57", "lang": "shell", "d": 3, "q": "Chercher le mot TODO dans tous les fichiers du dossier courant et des sous-dossiers", "a": ["grep -r TODO .", "grep -R TODO .", "grep -rn TODO .", "grep -r \"TODO\" .", "grep -r TODO"], "x": ["find TODO .", "grep TODO ."], "h": "grep en mode récursif", "e": "`-r` parcourt toute l'arborescence. `-n` ajoute le numéro de ligne."},
{"id": "SH-58", "lang": "shell", "d": 3, "q": "Afficher la 1re colonne de data.csv, séparé par des virgules", "a": ["cut -d, -f1 data.csv", "cut -d\",\" -f1 data.csv", "cut -d \",\" -f1 data.csv", "cut -d , -f 1 data.csv", "cut -d, -f 1 data.csv", "cut -f1 -d, data.csv"], "x": ["cut -f1 data.csv", "split -f1 data.csv"], "h": "cut, avec le délimiteur et le numéro de champ", "e": "`-d` donne le séparateur, `-f` le numéro de colonne. Sans `-d`, cut attend des tabulations."},
{"id": "SH-59", "lang": "shell", "d": 3, "q": "Retrouver dans l'historique les commandes contenant ssh", "a": ["history | grep ssh"], "x": ["grep ssh history", "history -s ssh"], "h": "history, un tube, grep", "e": "`history | grep motif` filtre l'historique. On peut aussi faire Ctrl + R et taper le motif."},
{"id": "SH-60", "lang": "shell", "d": 3, "q": "Lancer script.sh en arrière-plan", "a": ["./script.sh &", "./script.sh&", "bash script.sh &", "sh script.sh &"], "x": ["./script.sh bg", "bg ./script.sh"], "h": "Un symbole à la fin de la commande", "e": "Le `&` final rend la main tout de suite. `jobs` liste les tâches de fond, `fg` en ramène une au premier plan."},
// ───────── PYTHON ─────────
{"id": "PY-01", "lang": "python", "d": 1, "q": "Afficher le texte Bonjour", "a": ["print(\"Bonjour\")"], "x": ["echo \"Bonjour\"", "printf(\"Bonjour\")"], "h": "La fonction qui imprime à l'écran", "e": "`print()` affiche une valeur. Guillemets simples ou doubles, Python accepte les deux."},
{"id": "PY-02", "lang": "python", "d": 1, "q": "Créer une variable age qui vaut 25", "a": ["age = 25"], "x": ["age == 25", "var age = 25"], "h": "Un seul signe égal", "e": "`=` affecte une valeur. `==` compare deux valeurs. Pas de mot-clé `var` en Python."},
{"id": "PY-03", "lang": "python", "d": 1, "q": "Afficher le type de la variable x", "a": ["print(type(x))", "type(x)"], "x": ["typeof(x)", "x.type()"], "h": "Une fonction intégrée de quatre lettres", "e": "`type(x)` renvoie le type : int, str, list… `typeof` c'est en JavaScript."},
{"id": "PY-04", "lang": "python", "d": 1, "q": "Demander une saisie à l'utilisateur et la stocker dans nom", "a": ["nom = input()", "re:^nom=input\\(\".*\"\\)$"], "x": ["nom = read()", "nom = scan()"], "h": "Le contraire d'output", "e": "`input()` attend une saisie au clavier et renvoie toujours une chaîne. On peut passer un message : `input(\"Ton nom ? \")`."},
{"id": "PY-05", "lang": "python", "d": 1, "q": "Obtenir la longueur de la chaîne mot", "a": ["len(mot)", "print(len(mot))"], "x": ["mot.length", "length(mot)"], "h": "Abréviation de length, en trois lettres", "e": "`len()` marche sur les chaînes, les listes, les dictionnaires… `.length` c'est en JavaScript."},
{"id": "PY-06", "lang": "python", "d": 1, "q": "Créer une liste fruits contenant \"pomme\" et \"kiwi\"", "a": ["fruits = [\"pomme\", \"kiwi\"]"], "x": ["fruits = (\"pomme\", \"kiwi\")", "fruits = {\"pomme\", \"kiwi\"}"], "h": "Les crochets", "e": "Crochets `[]` pour une liste, parenthèses pour un tuple (non modifiable), accolades pour un ensemble ou un dictionnaire."},
{"id": "PY-07", "lang": "python", "d": 1, "q": "Avec quel symbole commence un commentaire ?", "a": ["#", "re:^#.*"], "x": ["//", "<!--"], "h": "Le dièse", "e": "`# commentaire` : tout ce qui suit le dièse est ignoré. `//` sert en JavaScript, `<!--` en HTML."},
{"id": "PY-08", "lang": "python", "d": 1, "q": "Convertir la chaîne \"42\" en nombre entier", "a": ["int(\"42\")"], "x": ["str(\"42\")", "integer(\"42\")"], "h": "Le type entier, en trois lettres", "e": "`int()` convertit en entier, `float()` en décimal, `str()` en chaîne."},
{"id": "PY-22", "lang": "python", "d": 1, "q": "Afficher la somme de 3 et 4", "a": ["print(3 + 4)", "print(4 + 3)", "3 + 4"], "x": ["print(\"3 + 4\")", "sum(3, 4)"], "h": "print, et un calcul sans guillemets", "e": "Sans guillemets, Python calcule. Entre guillemets, `\"3 + 4\"` serait juste du texte."},
{"id": "PY-23", "lang": "python", "d": 1, "q": "Créer une variable prenom contenant le texte Ada", "a": ["prenom = \"Ada\""], "x": ["prenom = Ada", "\"Ada\" = prenom"], "h": "Le texte va entre guillemets", "e": "Sans guillemets, Python chercherait une variable nommée Ada. La variable est toujours à gauche du `=`."},
{"id": "PY-24", "lang": "python", "d": 1, "q": "Calculer le reste de la division de 10 par 3", "a": ["10 % 3", "print(10 % 3)"], "x": ["10 / 3", "10 // 3"], "h": "Le symbole pourcentage", "e": "`%` (modulo) donne le reste : 1. Très utilisé pour tester si un nombre est pair : `n % 2 == 0`."},
{"id": "PY-25", "lang": "python", "d": 1, "q": "Calculer la division entière de 10 par 3", "a": ["10 // 3", "print(10 // 3)"], "x": ["10 / 3", "10 % 3"], "h": "Deux barres obliques", "e": "`//` donne 3 (sans la partie décimale). `/` donne 3.333…"},
{"id": "PY-26", "lang": "python", "d": 1, "q": "Calculer 2 puissance 8", "a": ["2 ** 8", "print(2 ** 8)", "pow(2, 8)"], "x": ["2 ^ 8", "2 * 8"], "h": "Deux étoiles", "e": "`**` est la puissance : 256. Attention, `^` est un « ou exclusif » binaire, pas une puissance."},
{"id": "PY-27", "lang": "python", "d": 1, "q": "Convertir le nombre 42 en chaîne de caractères", "a": ["str(42)"], "x": ["int(42)", "string(42)"], "h": "Le type chaîne, en trois lettres", "e": "`str()` convertit en texte. Utile pour coller un nombre à une phrase : `\"Score : \" + str(42)`."},
{"id": "PY-28", "lang": "python", "d": 1, "q": "Écrire la valeur booléenne vrai", "a": ["True"], "x": ["true", "TRUE"], "h": "Avec une majuscule", "e": "Python écrit `True` et `False` avec une majuscule. `true` en minuscules, c'est JavaScript."},
{"id": "PY-29", "lang": "python", "d": 1, "q": "Tester si a est égal à b", "a": ["a == b", "print(a == b)"], "x": ["a = b", "a === b"], "h": "Deux signes égal", "e": "`==` compare et renvoie True ou False. Un seul `=` affecte une valeur. `===` n'existe pas en Python."},
{"id": "PY-30", "lang": "python", "d": 1, "q": "Écrire la valeur qui représente « rien »", "a": ["None"], "x": ["null", "nil"], "h": "Aucun, en anglais, avec une majuscule", "e": "`None` signifie l'absence de valeur. C'est ce que renvoie une fonction sans `return`."},
{"id": "PY-31", "lang": "python", "d": 1, "q": "Arrondir 3.14159 à deux décimales", "a": ["round(3.14159, 2)", "print(round(3.14159, 2))"], "x": ["round(3.14159)", "round(2, 3.14159)"], "h": "round, puis le nombre de décimales", "e": "`round(x, 2)` donne 3.14. Sans second argument, on obtient un entier : 3."},
{"id": "PY-32", "lang": "python", "d": 1, "q": "Obtenir la valeur absolue de -7", "a": ["abs(-7)", "print(abs(-7))"], "x": ["absolute(-7)", "math.abs(-7)"], "h": "Trois lettres", "e": "`abs()` renvoie la distance à zéro : 7. Elle est intégrée, pas besoin d'importer math."},
{"id": "PY-33", "lang": "python", "d": 1, "q": "Créer une liste vide nommée panier", "a": ["panier = []", "panier = list()"], "x": ["panier = {}", "panier = ()"], "h": "Des crochets vides", "e": "`[]` crée une liste vide. `{}` crée un dictionnaire vide, `()` un tuple vide."},
{"id": "PY-09", "lang": "python", "d": 2, "q": "Ajouter \"banane\" à la fin de la liste fruits", "a": ["fruits.append(\"banane\")"], "x": ["fruits.add(\"banane\")", "fruits.push(\"banane\")"], "h": "Une méthode qui veut dire « ajouter à la suite »", "e": "`.append()` ajoute un élément en fin de liste. `.add()` existe pour les ensembles, `.push()` en JavaScript."},
{"id": "PY-10", "lang": "python", "d": 2, "q": "Écrire la première ligne d'une boucle qui répète 5 fois avec la variable i", "a": ["for i in range(5):"], "x": ["for i in 5:", "for (i = 0; i < 5; i++)"], "h": "for… in… et la fonction range", "e": "`range(5)` produit 0, 1, 2, 3, 4. Les deux-points ouvrent le bloc indenté."},
{"id": "PY-11", "lang": "python", "d": 2, "q": "Écrire la première ligne d'un test : si x est supérieur à 10", "a": ["if x > 10:", "if (x > 10):"], "x": ["if x > 10", "if (x > 10) {"], "h": "N'oublie pas ce qui ouvre le bloc", "e": "`if condition:` puis un bloc indenté. Pas d'accolades en Python, c'est l'indentation qui compte."},
{"id": "PY-12", "lang": "python", "d": 2, "q": "Mettre la chaîne nom en majuscules", "a": ["nom.upper()", "print(nom.upper())"], "x": ["upper(nom)", "nom.toUpperCase()"], "h": "Une méthode de chaîne, « haut » en anglais", "e": "`.upper()` renvoie une nouvelle chaîne en majuscules, `.lower()` en minuscules."},
{"id": "PY-13", "lang": "python", "d": 2, "q": "Importer le module random", "a": ["import random"], "x": ["include random", "require(\"random\")"], "h": "Le mot-clé qui importe", "e": "`import random` donne accès à `random.randint()`, `random.choice()`…"},
{"id": "PY-14", "lang": "python", "d": 2, "q": "Obtenir le premier élément de la liste fruits", "a": ["fruits[0]", "print(fruits[0])"], "x": ["fruits[1]", "fruits.first()"], "h": "Les index commencent à…", "e": "Les index commencent à 0. `fruits[-1]` donne le dernier élément."},
{"id": "PY-15", "lang": "python", "d": 2, "q": "Afficher Salut suivi de la variable nom avec une f-string", "a": ["print(f\"Salut {nom}\")"], "x": ["print(\"Salut {nom}\")", "print(Salut + nom)"], "h": "Une lettre devant les guillemets, la variable entre accolades", "e": "Le préfixe `f` permet d'insérer des variables entre accolades : `f\"Salut {nom}\"`."},
{"id": "PY-34", "lang": "python", "d": 2, "q": "Obtenir le dernier élément de la liste fruits", "a": ["fruits[-1]", "print(fruits[-1])", "fruits[len(fruits) - 1]"], "x": ["fruits[len(fruits)]", "fruits.last()"], "h": "Un index négatif", "e": "`-1` désigne le dernier élément, `-2` l'avant-dernier. `fruits[len(fruits)]` provoque une IndexError."},
{"id": "PY-35", "lang": "python", "d": 2, "q": "Obtenir les 3 premiers éléments de la liste fruits", "a": ["fruits[:3]", "fruits[0:3]", "print(fruits[:3])"], "x": ["fruits[3]", "fruits[1:3]"], "h": "Une tranche avec deux-points", "e": "`[:3]` prend les index 0, 1 et 2. La borne de fin est toujours exclue."},
{"id": "PY-36", "lang": "python", "d": 2, "q": "Trier la liste notes sur place", "a": ["notes.sort()"], "x": ["sort(notes)", "notes.sorted()"], "h": "Une méthode de liste", "e": "`.sort()` modifie la liste elle-même et renvoie None. `sorted(notes)` crée une nouvelle liste triée."},
{"id": "PY-37", "lang": "python", "d": 2, "q": "Retirer et récupérer le dernier élément de la liste pile", "a": ["pile.pop()"], "x": ["pile.remove()", "pile.pop(0)"], "h": "Comme une bulle qui éclate", "e": "`.pop()` enlève et renvoie le dernier élément. `.pop(0)` prendrait le premier."},
{"id": "PY-38", "lang": "python", "d": 2, "q": "Tester si \"kiwi\" fait partie de la liste fruits", "a": ["\"kiwi\" in fruits", "print(\"kiwi\" in fruits)"], "x": ["fruits.contains(\"kiwi\")", "fruits.has(\"kiwi\")"], "h": "Un mot-clé de deux lettres", "e": "`in` renvoie True ou False. Il marche aussi sur les chaînes et les clés de dictionnaire."},
{"id": "PY-39", "lang": "python", "d": 2, "q": "Découper la chaîne phrase en liste de mots", "a": ["phrase.split()", "phrase.split(\" \")"], "x": ["split(phrase)", "phrase.explode()"], "h": "Séparer, en anglais", "e": "`.split()` coupe sur les espaces. `.split(\",\")` couperait sur les virgules."},
{"id": "PY-40", "lang": "python", "d": 2, "q": "Assembler la liste mots en une chaîne, avec un espace entre chaque mot", "a": ["\" \".join(mots)"], "x": ["mots.join(\" \")", "join(mots, \" \")"], "h": "La méthode s'appelle sur le séparateur", "e": "`\" \".join(mots)` : c'est le séparateur qui porte la méthode. `mots.join()` est la syntaxe JavaScript."},
{"id": "PY-41", "lang": "python", "d": 2, "q": "Remplacer \"chat\" par \"chien\" dans la chaîne texte", "a": ["texte.replace(\"chat\", \"chien\")", "texte = texte.replace(\"chat\", \"chien\")"], "x": ["texte.replace(\"chien\", \"chat\")", "replace(texte, \"chat\", \"chien\")"], "h": "L'ancien d'abord, le nouveau ensuite", "e": "`.replace(ancien, nouveau)` renvoie une nouvelle chaîne : les chaînes ne sont jamais modifiées sur place."},
{"id": "PY-42", "lang": "python", "d": 2, "q": "Retirer les espaces au début et à la fin de la chaîne saisie", "a": ["saisie.strip()", "saisie = saisie.strip()"], "x": ["saisie.trim()", "strip(saisie)"], "h": "Dépouiller, en anglais", "e": "`.strip()` nettoie les deux bords, `.lstrip()` la gauche, `.rstrip()` la droite. `.trim()` c'est JavaScript."},
{"id": "PY-43", "lang": "python", "d": 2, "q": "Ajouter 1 à la variable score", "a": ["score += 1", "score = score + 1"], "x": ["score++", "score =+ 1"], "h": "Un opérateur raccourci avec +", "e": "`+=` ajoute et réaffecte. `score++` n'existe pas en Python, et `=+ 1` vaut simplement 1."},
{"id": "PY-44", "lang": "python", "d": 2, "q": "Écrire la première ligne d'une boucle qui tourne tant que n est positif", "a": ["while n > 0:", "while 0 < n:"], "x": ["while (n > 0) {", "loop n > 0:"], "h": "while, la condition, deux-points", "e": "`while condition:` répète le bloc tant que la condition est vraie. Pense à faire évoluer n, sinon la boucle est infinie."},
{"id": "PY-45", "lang": "python", "d": 2, "q": "Associer la valeur 12 à la clé \"alice\" dans le dictionnaire notes", "a": ["notes[\"alice\"] = 12"], "x": ["notes.alice = 12", "notes(\"alice\") = 12"], "h": "Crochets, comme pour une liste", "e": "`d[clé] = valeur` crée ou remplace l'entrée. La notation pointée `notes.alice` c'est JavaScript."},
{"id": "PY-46", "lang": "python", "d": 2, "q": "Obtenir les clés du dictionnaire notes", "a": ["notes.keys()", "list(notes.keys())", "list(notes)"], "x": ["notes.keys", "keys(notes)"], "h": "Clés, en anglais, avec des parenthèses", "e": "`.keys()` renvoie les clés, `.values()` les valeurs, `.items()` les paires."},
{"id": "PY-16", "lang": "python", "d": 3, "q": "Écrire la première ligne d'une fonction carre qui prend un paramètre x", "a": ["def carre(x):"], "x": ["function carre(x):", "def carre x:"], "h": "define", "e": "`def nom(paramètres):` puis le corps indenté, souvent terminé par `return`."},
{"id": "PY-17", "lang": "python", "d": 3, "q": "Créer un dictionnaire vide nommé scores", "a": ["scores = {}", "scores = dict()"], "x": ["scores = []", "scores = ()"], "h": "Accolades vides", "e": "`{}` crée un dictionnaire vide. Pour un ensemble vide il faut écrire `set()`."},
{"id": "PY-18", "lang": "python", "d": 3, "q": "Créer la liste carres des carrés de 0 à 9 en une seule ligne", "a": ["carres = [i**2 for i in range(10)]", "carres = [i*i for i in range(10)]", "carres = [x**2 for x in range(10)]", "carres = [x*x for x in range(10)]", "carres = [n**2 for n in range(10)]", "carres = [n*n for n in range(10)]"], "x": ["carres = [for i in range(10): i**2]", "carres = (i^2 for i in 10)"], "h": "Une liste en compréhension : [expression for … in …]", "e": "`[i**2 for i in range(10)]` est une liste en compréhension. `**` est la puissance ; `^` est un « ou exclusif »."},
{"id": "PY-19", "lang": "python", "d": 3, "q": "Ouvrir data.txt en lecture avec with, dans la variable f (première ligne)", "a": ["with open(\"data.txt\") as f:", "with open(\"data.txt\", \"r\") as f:"], "x": ["open(\"data.txt\") as f:", "with f = open(\"data.txt\"):"], "h": "with open(…) as …:", "e": "`with` ferme le fichier automatiquement à la fin du bloc, même en cas d'erreur."},
{"id": "PY-20", "lang": "python", "d": 3, "q": "Quel mot-clé ouvre le bloc de code à surveiller en cas d'erreur ?", "a": ["try:", "try"], "x": ["catch:", "except:"], "h": "Essayer, en anglais", "e": "`try:` exécute un bloc ; si une erreur survient, Python passe au bloc `except:`. `catch` c'est en Java ou JavaScript."},
{"id": "PY-21", "lang": "python", "d": 3, "q": "Créer une fonction anonyme double qui renvoie x multiplié par 2", "a": ["double = lambda x: x * 2", "double = lambda x: 2 * x", "double = lambda x: x + x"], "x": ["double = def x: x * 2", "double = x => x * 2"], "h": "Le mot-clé grec", "e": "`lambda paramètres: expression` crée une petite fonction sur une ligne. `=>` c'est la syntaxe JavaScript."},
{"id": "PY-47", "lang": "python", "d": 3, "q": "Parcourir fruits avec l'index i et l'élément f (première ligne)", "a": ["for i, f in enumerate(fruits):"], "x": ["for i, f in fruits:", "for i, f in range(fruits):"], "h": "Une fonction qui numérote", "e": "`enumerate()` fournit les paires (index, élément). Bien plus lisible que `range(len(fruits))`."},
{"id": "PY-48", "lang": "python", "d": 3, "q": "Parcourir les clés k et les valeurs v du dictionnaire d (première ligne)", "a": ["for k, v in d.items():"], "x": ["for k, v in d:", "for k, v in d.keys():"], "h": "La méthode qui donne les paires", "e": "`.items()` renvoie des couples (clé, valeur). Parcourir `d` seul ne donne que les clés."},
{"id": "PY-49", "lang": "python", "d": 3, "q": "Écrire la ligne qui intercepte une ValueError", "a": ["except ValueError:", "except ValueError as e:", "except ValueError as err:"], "x": ["catch ValueError:", "except: ValueError"], "h": "except, puis le type d'erreur", "e": "`except ValueError:` ne capture que ce type d'erreur. `as e` donne accès au message."},
{"id": "PY-50", "lang": "python", "d": 3, "q": "Déclencher une ValueError avec le message \"négatif\"", "a": ["raise ValueError(\"négatif\")"], "x": ["throw ValueError(\"négatif\")", "raise \"négatif\""], "h": "Lever, en anglais", "e": "`raise` déclenche une exception. `throw` c'est Java ou JavaScript, et on ne peut pas lever une simple chaîne."},
{"id": "PY-51", "lang": "python", "d": 3, "q": "Écrire la première ligne de la classe Chat", "a": ["class Chat:", "class Chat():", "class Chat(object):"], "x": ["def Chat:", "class chat() {"], "h": "class, le nom en majuscule, deux-points", "e": "`class Nom:` déclare une classe. Par convention, les noms de classes commencent par une majuscule."},
{"id": "PY-52", "lang": "python", "d": 3, "q": "Écrire la première ligne du constructeur d'une classe, qui reçoit nom", "a": ["def __init__(self, nom):"], "x": ["def __init__(nom):", "def constructor(self, nom):"], "h": "Deux tirets bas de chaque côté, et self en premier", "e": "`__init__` est appelé à la création de l'objet. `self` désigne l'objet lui-même et vient toujours en premier."},
{"id": "PY-53", "lang": "python", "d": 3, "q": "Importer uniquement la fonction sqrt du module math", "a": ["from math import sqrt"], "x": ["import sqrt from math", "import math.sqrt"], "h": "from… import…", "e": "`from math import sqrt` permet d'écrire `sqrt(9)` directement, sans `math.` devant."},
{"id": "PY-54", "lang": "python", "d": 3, "q": "Créer la liste pairs des nombres pairs de 0 à 20 inclus, en compréhension", "a": ["pairs = [n for n in range(21) if n % 2 == 0]", "pairs = [i for i in range(21) if i % 2 == 0]", "pairs = [x for x in range(21) if x % 2 == 0]", "pairs = [n for n in range(0, 21, 2)]", "pairs = list(range(0, 21, 2))"], "x": ["pairs = [n for n in range(20) if n % 2]", "pairs = [n if n % 2 == 0 for n in range(21)]"], "h": "[… for … in range(…) if …]", "e": "Le filtre `if` se place à la fin. `range(21)` va jusqu'à 20 inclus. `range(0, 21, 2)` avance de 2 en 2."},
{"id": "PY-55", "lang": "python", "d": 3, "q": "Créer le dictionnaire carres associant chaque n de 1 à 5 à son carré, en compréhension", "a": ["carres = {n: n**2 for n in range(1, 6)}", "carres = {n: n*n for n in range(1, 6)}", "carres = {i: i**2 for i in range(1, 6)}", "carres = {i: i*i for i in range(1, 6)}", "carres = {x: x**2 for x in range(1, 6)}", "carres = {x: x*x for x in range(1, 6)}"], "x": ["carres = [n: n**2 for n in range(1, 6)]", "carres = {n**2 for n in range(1, 6)}"], "h": "Accolades, et clé: valeur", "e": "`{clé: valeur for …}` crée un dictionnaire. Sans les deux-points, on obtient un ensemble (set)."},
{"id": "PY-56", "lang": "python", "d": 3, "q": "Définir la fonction salut avec un paramètre nom qui vaut \"toi\" par défaut (première ligne)", "a": ["def salut(nom=\"toi\"):"], "x": ["def salut(nom: \"toi\"):", "def salut(nom == \"toi\"):"], "h": "Un signe égal dans les parenthèses", "e": "`nom=\"toi\"` rend l'argument facultatif : `salut()` et `salut(\"Ada\")` marchent tous les deux."},
{"id": "PY-57", "lang": "python", "d": 3, "q": "Définir la fonction moyenne qui accepte un nombre quelconque d'arguments positionnels (première ligne)", "a": ["def moyenne(*nombres):", "def moyenne(*args):"], "x": ["def moyenne(nombres...):", "def moyenne(**nombres):"], "h": "Une étoile devant le nom du paramètre", "e": "`*nombres` regroupe tous les arguments dans un tuple. `**` regroupe les arguments nommés dans un dictionnaire."},
{"id": "PY-58", "lang": "python", "d": 3, "q": "Écrire le test qui lance le code seulement si le fichier est exécuté directement", "a": ["if __name__ == \"__main__\":"], "x": ["if __main__:", "if name == \"main\":"], "h": "__name__ et __main__, avec leurs tirets bas", "e": "Ce test évite d'exécuter le programme quand le fichier est importé comme module par un autre."},
{"id": "PY-59", "lang": "python", "d": 3, "q": "Lire tout le contenu du fichier ouvert f dans la variable texte", "a": ["texte = f.read()"], "x": ["texte = f.readline()", "texte = read(f)"], "h": "Lire, en anglais, sur l'objet fichier", "e": "`.read()` lit tout d'un coup, `.readline()` une seule ligne, `.readlines()` une liste de lignes."},
{"id": "PY-60", "lang": "python", "d": 3, "q": "Créer la liste tries : les mots de mots, triés par longueur", "a": ["tries = sorted(mots, key=len)"], "x": ["tries = mots.sort(key=len)", "tries = sorted(mots, len)"], "h": "sorted, avec un paramètre key", "e": "`key=len` trie selon la longueur. `mots.sort()` renvoie None : tries vaudrait None."},
// ───────── HTML ─────────
{"id": "HT-01", "lang": "html", "d": 1, "q": "Écrire un titre principal contenant Bienvenue", "a": ["<h1>Bienvenue</h1>"], "x": ["<title>Bienvenue</title>", "<h6>Bienvenue</h6>"], "h": "heading de niveau 1", "e": "`<h1>` est le titre le plus important de la page, `<h6>` le moins important. `<title>` est le titre de l'onglet, dans le head."},
{"id": "HT-02", "lang": "html", "d": 1, "q": "Écrire un paragraphe contenant Bonjour", "a": ["<p>Bonjour</p>"], "x": ["<para>Bonjour</para>", "<text>Bonjour</text>"], "h": "Une seule lettre", "e": "`<p>` délimite un paragraphe de texte."},
{"id": "HT-03", "lang": "html", "d": 1, "q": "Insérer un saut de ligne", "a": ["<br>", "<br/>"], "x": ["<lb>", "<break>"], "h": "break, en deux lettres", "e": "`<br>` est une balise vide : elle n'a pas de balise fermante."},
{"id": "HT-04", "lang": "html", "d": 1, "q": "Mettre le mot important en gras (importance forte)", "a": ["<strong>important</strong>", "<b>important</b>"], "x": ["<bold>important</bold>", "<em>important</em>"], "h": "« Fort » en anglais", "e": "`<strong>` indique une importance forte, affichée en gras. `<em>` met l'accent, en italique."},
{"id": "HT-05", "lang": "html", "d": 1, "q": "Créer un lien vers https://example.com avec le texte Site", "a": ["<a href=\"https://example.com\">Site</a>"], "x": ["<link href=\"https://example.com\">Site</link>", "<a src=\"https://example.com\">Site</a>"], "h": "La balise a, et l'attribut href", "e": "`<a href=\"…\">` crée un lien (a = anchor). `<link>` sert à relier une feuille de style."},
{"id": "HT-06", "lang": "html", "d": 1, "q": "Écrire un commentaire HTML contenant à faire", "a": ["<!-- à faire -->", "re:^<!--.*-->$"], "x": ["// à faire", "# à faire"], "h": "Ça commence par <!--", "e": "`<!-- … -->` : le navigateur ignore ce texte. Visible quand même dans le code source !"},
{"id": "HT-07", "lang": "html", "d": 1, "q": "Insérer une ligne horizontale de séparation", "a": ["<hr>", "<hr/>"], "x": ["<line>", "<br>"], "h": "horizontal rule", "e": "`<hr>` trace une ligne de séparation thématique. Balise vide, comme `<br>`."},
{"id": "HT-22", "lang": "html", "d": 1, "q": "Écrire un titre de niveau 2 contenant Partie 1", "a": ["<h2>Partie 1</h2>"], "x": ["<h1>Partie 1</h1>", "<header>Partie 1</header>"], "h": "heading de niveau 2", "e": "Les titres vont de `<h1>` à `<h6>`. On ne saute pas de niveau : un `<h3>` vient après un `<h2>`."},
{"id": "HT-23", "lang": "html", "d": 1, "q": "Mettre le mot vite en italique (emphase)", "a": ["<em>vite</em>", "<i>vite</i>"], "x": ["<it>vite</it>", "<strong>vite</strong>"], "h": "emphasis", "e": "`<em>` met l'accent sur un mot, affiché en italique. Les lecteurs d'écran le prononcent différemment."},
{"id": "HT-24", "lang": "html", "d": 1, "q": "Écrire un élément de liste contenant Café", "a": ["<li>Café</li>"], "x": ["<item>Café</item>", "<ul>Café</ul>"], "h": "list item", "e": "`<li>` se place toujours dans une `<ul>` ou une `<ol>`."},
{"id": "HT-25", "lang": "html", "d": 1, "q": "Ouvrir la balise qui contient tout le contenu visible de la page", "a": ["<body>"], "x": ["<head>", "<page>"], "h": "Le corps", "e": "`<body>` contient ce qui s'affiche. `<head>` contient les informations invisibles (titre, encodage, styles)."},
{"id": "HT-26", "lang": "html", "d": 1, "q": "Ouvrir la balise qui contient les informations invisibles de la page", "a": ["<head>"], "x": ["<header>", "<meta>"], "h": "La tête", "e": "`<head>` contient titre, encodage, liens CSS. Ne pas confondre avec `<header>`, l'en-tête visible de la page."},
{"id": "HT-27", "lang": "html", "d": 1, "q": "Donner le titre Accueil à l'onglet du navigateur", "a": ["<title>Accueil</title>"], "x": ["<h1>Accueil</h1>", "<tab>Accueil</tab>"], "h": "title, dans le head", "e": "`<title>` s'affiche dans l'onglet et dans les résultats des moteurs de recherche."},
{"id": "HT-28", "lang": "html", "d": 1, "q": "Mettre le chiffre 2 en exposant", "a": ["<sup>2</sup>"], "x": ["<sub>2</sub>", "<up>2</up>"], "h": "superscript", "e": "`<sup>` pour l'exposant (m²), `<sub>` pour l'indice (H₂O)."},
{"id": "HT-29", "lang": "html", "d": 1, "q": "Écrire H2O avec le 2 en indice", "a": ["H<sub>2</sub>O"], "x": ["H<sup>2</sup>O", "H<low>2</low>O"], "h": "subscript", "e": "`<sub>` place le texte en bas. Utile en chimie et en maths."},
{"id": "HT-30", "lang": "html", "d": 1, "q": "Surligner le mot clé", "a": ["<mark>clé</mark>"], "x": ["<highlight>clé</highlight>", "<em>clé</em>"], "h": "Marquer, en anglais", "e": "`<mark>` surligne en jaune par défaut, comme un fluo sur une feuille."},
{"id": "HT-31", "lang": "html", "d": 1, "q": "Afficher le mot print comme du code dans une phrase", "a": ["<code>print</code>"], "x": ["<program>print</program>", "<script>print</script>"], "h": "Le mot code, tout simplement", "e": "`<code>` affiche en police à chasse fixe. `<script>` exécuterait du JavaScript, rien à voir."},
{"id": "HT-32", "lang": "html", "d": 1, "q": "Créer un lien vers la page contact.html avec le texte Contact", "a": ["<a href=\"contact.html\">Contact</a>", "<a href=\"./contact.html\">Contact</a>"], "x": ["<a link=\"contact.html\">Contact</a>", "<a>contact.html</a>"], "h": "a, avec href", "e": "Un chemin sans `https://` est relatif : le navigateur cherche contact.html dans le même dossier."},
{"id": "HT-33", "lang": "html", "d": 1, "q": "Créer un bloc générique contenant Bonjour", "a": ["<div>Bonjour</div>"], "x": ["<block>Bonjour</block>", "<box>Bonjour</box>"], "h": "division", "e": "`<div>` est une boîte sans signification, utilisée pour la mise en page avec le CSS."},
{"id": "HT-34", "lang": "html", "d": 1, "q": "Entourer le mot mot d'un élément en ligne générique", "a": ["<span>mot</span>"], "x": ["<inline>mot</inline>", "<div>mot</div>"], "h": "Une travée, en anglais", "e": "`<span>` est l'équivalent en ligne de `<div>` : il ne crée pas de retour à la ligne."},
{"id": "HT-08", "lang": "html", "d": 2, "q": "Afficher l'image chat.jpg avec le texte alternatif Un chat", "a": ["<img src=\"chat.jpg\" alt=\"Un chat\">", "<img alt=\"Un chat\" src=\"chat.jpg\">"], "x": ["<image src=\"chat.jpg\" alt=\"Un chat\">", "<img href=\"chat.jpg\" alt=\"Un chat\">"], "h": "img, src et alt", "e": "`src` donne le chemin de l'image, `alt` le texte lu par les lecteurs d'écran ou affiché si l'image ne charge pas."},
{"id": "HT-09", "lang": "html", "d": 2, "q": "Créer une liste à puces avec un seul élément Pomme", "a": ["<ul><li>Pomme</li></ul>"], "x": ["<ol><li>Pomme</li></ol>", "<list><item>Pomme</item></list>"], "h": "unordered list, list item", "e": "`<ul>` = liste à puces, `<ol>` = liste numérotée. Chaque élément va dans un `<li>`."},
{"id": "HT-10", "lang": "html", "d": 2, "q": "Créer une liste numérotée avec un seul élément Un", "a": ["<ol><li>Un</li></ol>"], "x": ["<ul><li>Un</li></ul>", "<nl><li>Un</li></nl>"], "h": "ordered list", "e": "`<ol>` numérote automatiquement ses `<li>`. L'attribut `start` change le premier numéro."},
{"id": "HT-11", "lang": "html", "d": 2, "q": "Quel attribut de lien ouvre la page dans un nouvel onglet ?", "a": ["target=\"_blank\""], "x": ["new=\"tab\"", "href=\"_blank\""], "h": "La cible, avec un tiret bas", "e": "`target=\"_blank\"` ouvre un nouvel onglet. Bon réflexe sécurité : ajouter `rel=\"noopener\"`."},
{"id": "HT-12", "lang": "html", "d": 2, "q": "Créer un champ de saisie de texte", "a": ["<input type=\"text\">", "<input>", "<input type=\"text\"/>"], "x": ["<textfield>", "<input type=\"input\">"], "h": "input, avec un type", "e": "`<input type=\"text\">` est le type par défaut. Il existe aussi email, password, number, date…"},
{"id": "HT-13", "lang": "html", "d": 2, "q": "Créer un bouton avec le texte Envoyer", "a": ["<button>Envoyer</button>", "<input type=\"submit\" value=\"Envoyer\">", "<button type=\"submit\">Envoyer</button>"], "x": ["<btn>Envoyer</btn>", "<click>Envoyer</click>"], "h": "Le mot anglais en entier", "e": "`<button>` peut contenir du texte ou une icône. Dans un formulaire, il envoie le formulaire par défaut."},
{"id": "HT-14", "lang": "html", "d": 2, "q": "Écrire la déclaration de type de document HTML5 (toute première ligne)", "a": ["<!DOCTYPE html>"], "x": ["<html5>", "<!DOCTYPE html5>"], "h": "Commence par <! et parle de type de document", "e": "`<!DOCTYPE html>` indique au navigateur d'utiliser le mode standard HTML5."},
{"id": "HT-35", "lang": "html", "d": 2, "q": "Créer une zone de saisie de texte sur plusieurs lignes", "a": ["<textarea></textarea>"], "x": ["<input type=\"multiline\">", "<textbox></textbox>"], "h": "text area", "e": "`<textarea>` a une balise fermante, contrairement à `<input>`. Les attributs `rows` et `cols` règlent sa taille."},
{"id": "HT-36", "lang": "html", "d": 2, "q": "Créer une case à cocher", "a": ["<input type=\"checkbox\">"], "x": ["<checkbox>", "<input type=\"check\">"], "h": "input, avec un type en un mot", "e": "`type=\"checkbox\"` ; l'attribut `checked` la coche par défaut."},
{"id": "HT-37", "lang": "html", "d": 2, "q": "Créer un champ de mot de passe", "a": ["<input type=\"password\">"], "x": ["<input type=\"hidden\">", "<password>"], "h": "input, type mot de passe en anglais", "e": "`type=\"password\"` masque les caractères. Attention : ça ne chiffre rien, c'est juste visuel."},
{"id": "HT-38", "lang": "html", "d": 2, "q": "Créer l'étiquette Email reliée au champ dont l'id est email", "a": ["<label for=\"email\">Email</label>"], "x": ["<label id=\"email\">Email</label>", "<label name=\"email\">Email</label>"], "h": "label, avec l'attribut for", "e": "`for` relie l'étiquette à l'`id` du champ : cliquer sur le texte active le champ. Indispensable pour l'accessibilité."},
{"id": "HT-39", "lang": "html", "d": 2, "q": "Créer une liste déroulante avec une seule option Paris", "a": ["<select><option>Paris</option></select>"], "x": ["<dropdown><option>Paris</option></dropdown>", "<select><item>Paris</item></select>"], "h": "select et option", "e": "`<select>` contient des `<option>`. L'attribut `value` d'une option est ce qui est envoyé au serveur."},
{"id": "HT-40", "lang": "html", "d": 2, "q": "Créer un lien qui ouvre un e-mail vers contact@exemple.fr, avec le texte Écrire", "a": ["<a href=\"mailto:contact@exemple.fr\">Écrire</a>"], "x": ["<a href=\"contact@exemple.fr\">Écrire</a>", "<a mail=\"contact@exemple.fr\">Écrire</a>"], "h": "href, avec le préfixe mailto:", "e": "`mailto:` ouvre la messagerie. Il existe aussi `tel:` pour lancer un appel."},
{"id": "HT-41", "lang": "html", "d": 2, "q": "Créer une cellule d'en-tête de tableau contenant Nom", "a": ["<th>Nom</th>"], "x": ["<td>Nom</td>", "<thead>Nom</thead>"], "h": "table header", "e": "`<th>` est une cellule d'en-tête, en gras et centrée par défaut. `<thead>` regroupe les lignes d'en-tête."},
{"id": "HT-42", "lang": "html", "d": 2, "q": "Créer un lien vers la section d'id contact de la même page, avec le texte Aller", "a": ["<a href=\"#contact\">Aller</a>"], "x": ["<a href=\"contact\">Aller</a>", "<a id=\"#contact\">Aller</a>"], "h": "Un dièse devant l'id", "e": "`#id` fait défiler la page jusqu'à l'élément qui porte cet id. C'est une ancre."},
{"id": "HT-43", "lang": "html", "d": 2, "q": "Créer un bloc de citation contenant Citation", "a": ["<blockquote>Citation</blockquote>"], "x": ["<quote>Citation</quote>", "<cite>Citation</cite>"], "h": "Un bloc qui cite", "e": "`<blockquote>` pour une citation longue, `<q>` pour une courte dans le texte, `<cite>` pour le titre d'une œuvre."},
{"id": "HT-44", "lang": "html", "d": 2, "q": "Créer un bouton radio appartenant au groupe taille", "a": ["<input type=\"radio\" name=\"taille\">", "<input name=\"taille\" type=\"radio\">"], "x": ["<radio name=\"taille\">", "<input type=\"radio\" id=\"taille\">"], "h": "type radio, et name pour le groupe", "e": "Les boutons radio qui partagent le même `name` s'excluent : un seul peut être choisi."},
{"id": "HT-45", "lang": "html", "d": 2, "q": "Ouvrir la balise du contenu principal de la page", "a": ["<main>"], "x": ["<body>", "<center>"], "h": "Principal, en anglais", "e": "`<main>` contient le contenu propre à la page, une seule fois. Les lecteurs d'écran peuvent y sauter directement."},
{"id": "HT-46", "lang": "html", "d": 2, "q": "Ouvrir la balise d'un bloc de navigation", "a": ["<nav>"], "x": ["<navbar>", "<navigation>"], "h": "Trois lettres", "e": "`<nav>` regroupe les liens principaux du site. C'est une balise sémantique."},
{"id": "HT-47", "lang": "html", "d": 2, "q": "Ouvrir la balise du pied de page", "a": ["<footer>"], "x": ["<bottom>", "<foot>"], "h": "Le pied, en anglais", "e": "`<footer>` contient mentions légales, contact, liens secondaires. Son pendant en haut est `<header>`."},
{"id": "HT-15", "lang": "html", "d": 3, "q": "Lier la feuille de style style.css dans le head", "a": ["<link rel=\"stylesheet\" href=\"style.css\">", "<link href=\"style.css\" rel=\"stylesheet\">"], "x": ["<style src=\"style.css\">", "<css href=\"style.css\">"], "h": "link, rel et href", "e": "`<link rel=\"stylesheet\" href=\"…\">` relie un fichier CSS externe. `<style>` sert au CSS écrit directement dans la page."},
{"id": "HT-16", "lang": "html", "d": 3, "q": "Charger le fichier JavaScript app.js", "a": ["<script src=\"app.js\"></script>", "<script src=\"app.js\" defer></script>"], "x": ["<script href=\"app.js\"></script>", "<js src=\"app.js\">"], "h": "script, avec src, et sa balise fermante", "e": "`<script src=\"…\"></script>` : la balise fermante est obligatoire. `defer` attend que la page soit lue avant d'exécuter."},
{"id": "HT-17", "lang": "html", "d": 3, "q": "Déclarer l'encodage UTF-8 avec une balise meta", "a": ["<meta charset=\"UTF-8\">", "<meta charset=\"utf-8\"/>"], "x": ["<meta encoding=\"UTF-8\">", "<charset=\"UTF-8\">"], "h": "meta, attribut charset", "e": "`<meta charset=\"UTF-8\">` garantit que les accents s'affichent correctement. À placer tout en haut du head."},
{"id": "HT-18", "lang": "html", "d": 3, "q": "Créer un tableau d'une ligne avec une seule cellule Total", "a": ["<table><tr><td>Total</td></tr></table>"], "x": ["<table><row><cell>Total</cell></row></table>", "<table><td><tr>Total</tr></td></table>"], "h": "table, table row, table data", "e": "`<tr>` = ligne, `<td>` = cellule. Pour une cellule d'en-tête, on utilise `<th>`."},
{"id": "HT-19", "lang": "html", "d": 3, "q": "Créer un div vide avec la classe carte", "a": ["<div class=\"carte\"></div>"], "x": ["<div id=\"carte\"></div>", "<div style=\"carte\"></div>"], "h": "L'attribut utilisé par le CSS pour styliser plusieurs éléments", "e": "`class` peut être partagé par plusieurs éléments ; `id` doit être unique dans la page."},
{"id": "HT-20", "lang": "html", "d": 3, "q": "Ouvrir un formulaire qui envoie vers /inscription en POST", "a": ["<form action=\"/inscription\" method=\"post\">", "<form method=\"post\" action=\"/inscription\">"], "x": ["<form href=\"/inscription\" type=\"post\">", "<form src=\"/inscription\" method=\"send\">"], "h": "action et method", "e": "`action` = adresse de destination, `method` = GET (données dans l'URL) ou POST (données dans le corps de la requête)."},
{"id": "HT-21", "lang": "html", "d": 3, "q": "Créer un champ email obligatoire", "a": ["<input type=\"email\" required>", "<input required type=\"email\">", "<input type=\"email\" required=\"required\">", "<input type=\"email\" required/>"], "x": ["<input type=\"mail\" needed>", "<email required>"], "h": "type email et un attribut booléen", "e": "`required` empêche l'envoi si le champ est vide, et `type=\"email\"` vérifie le format. Le serveur doit quand même revérifier !"},
{"id": "HT-48", "lang": "html", "d": 3, "q": "Écrire la balise meta qui adapte la page aux écrans de téléphone", "a": ["<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">", "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">", "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">", "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">", "<meta content=\"width=device-width, initial-scale=1\" name=\"viewport\">", "<meta content=\"width=device-width, initial-scale=1.0\" name=\"viewport\">"], "x": ["<meta viewport=\"width=device-width\">", "<meta name=\"mobile\" content=\"width=device-width, initial-scale=1\">"], "h": "meta name viewport, width=device-width", "e": "Sans cette balise, les téléphones affichent la page comme sur un grand écran, en tout petit."},
{"id": "HT-49", "lang": "html", "d": 3, "q": "Insérer la vidéo film.mp4 avec les boutons de lecture", "a": ["<video src=\"film.mp4\" controls></video>", "<video controls src=\"film.mp4\"></video>", "<video src=\"film.mp4\" controls=\"controls\"></video>"], "x": ["<movie src=\"film.mp4\" controls></movie>", "<video href=\"film.mp4\" controls></video>"], "h": "video, src et un attribut booléen", "e": "`controls` affiche lecture, pause et volume. Sans lui, la vidéo n'a aucun bouton."},
{"id": "HT-50", "lang": "html", "d": 3, "q": "Insérer le son son.mp3 avec les boutons de lecture", "a": ["<audio src=\"son.mp3\" controls></audio>", "<audio controls src=\"son.mp3\"></audio>"], "x": ["<sound src=\"son.mp3\" controls></sound>", "<audio src=\"son.mp3\" play></audio>"], "h": "audio, src et controls", "e": "`<audio>` fonctionne comme `<video>`. `autoplay` est bloqué par la plupart des navigateurs tant que l'utilisateur n'a pas interagi."},
{"id": "HT-51", "lang": "html", "d": 3, "q": "Lien vers https://example.com, texte Site, ouvert dans un nouvel onglet, avec rel=\"noopener\"", "a": ["<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\">Site</a>", "<a href=\"https://example.com\" rel=\"noopener\" target=\"_blank\">Site</a>", "<a target=\"_blank\" href=\"https://example.com\" rel=\"noopener\">Site</a>", "<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener noreferrer\">Site</a>", "<a href=\"https://example.com\" rel=\"noopener noreferrer\" target=\"_blank\">Site</a>", "<a href=\"https://example.com\" target=\"_blank\" rel=\"noreferrer noopener\">Site</a>"], "x": ["<a href=\"https://example.com\" target=\"blank\" rel=\"noopener\">Site</a>", "<a href=\"https://example.com\" new=\"tab\" rel=\"noopener\">Site</a>"], "h": "href, target=\"_blank\", rel=\"noopener\"", "e": "`noopener` empêche la page ouverte d'agir sur la tienne via `window.opener` : une protection contre le hameçonnage."},
{"id": "HT-52", "lang": "html", "d": 3, "q": "Créer une cellule de tableau Total qui s'étend sur 2 colonnes", "a": ["<td colspan=\"2\">Total</td>", "<th colspan=\"2\">Total</th>"], "x": ["<td rowspan=\"2\">Total</td>", "<td merge=\"2\">Total</td>"], "h": "column span", "e": "`colspan` fusionne horizontalement, `rowspan` verticalement."},
{"id": "HT-53", "lang": "html", "d": 3, "q": "Créer un champ numérique qui accepte de 1 à 10", "a": ["<input type=\"number\" min=\"1\" max=\"10\">", "<input type=\"number\" max=\"10\" min=\"1\">", "<input min=\"1\" max=\"10\" type=\"number\">"], "x": ["<input type=\"number\" from=\"1\" to=\"10\">", "<input type=\"range\" from=\"1\" to=\"10\">"], "h": "type number, min et max", "e": "`min` et `max` bornent la valeur ; `step` règle le pas. Le serveur doit quand même revérifier."},
{"id": "HT-54", "lang": "html", "d": 3, "q": "Écrire la légende Un chat d'une figure", "a": ["<figcaption>Un chat</figcaption>"], "x": ["<caption>Un chat</caption>", "<legend>Un chat</legend>"], "h": "figure caption", "e": "`<figcaption>` va dans un `<figure>`. `<caption>` est la légende d'un tableau, `<legend>` celle d'un groupe de champs."},
{"id": "HT-55", "lang": "html", "d": 3, "q": "Créer un bouton OK qui n'envoie pas le formulaire", "a": ["<button type=\"button\">OK</button>"], "x": ["<button type=\"submit\">OK</button>", "<button submit=\"false\">OK</button>"], "h": "Le type le plus neutre", "e": "Dans un formulaire, un `<button>` envoie par défaut. `type=\"button\"` en fait un simple bouton, à piloter en JavaScript."},
{"id": "HT-56", "lang": "html", "d": 3, "q": "Quel attribut d'image retarde son chargement jusqu'à ce qu'elle approche de l'écran ?", "a": ["loading=\"lazy\""], "x": ["lazy=\"true\"", "defer=\"lazy\""], "h": "loading, avec la valeur paresseuse", "e": "`loading=\"lazy\"` accélère les pages longues : les images lointaines ne se chargent qu'au défilement."},
{"id": "HT-57", "lang": "html", "d": 3, "q": "Ouvrir la balise html d'une page rédigée en français", "a": ["<html lang=\"fr\">"], "x": ["<html language=\"fr\">", "<html lang=\"french\">"], "h": "lang, avec le code à deux lettres", "e": "`lang` aide les lecteurs d'écran à choisir la bonne prononciation, et les traducteurs automatiques."},
{"id": "HT-58", "lang": "html", "d": 3, "q": "Ouvrir la balise d'un contenu autonome, comme un billet de blog", "a": ["<article>"], "x": ["<section>", "<post>"], "h": "Un article", "e": "`<article>` a du sens seul (billet, fiche produit). `<section>` regroupe une partie thématique d'une page."},
{"id": "HT-59", "lang": "html", "d": 3, "q": "Créer un champ texte affichant l'indication Ton nom quand il est vide", "a": ["<input type=\"text\" placeholder=\"Ton nom\">", "<input placeholder=\"Ton nom\">", "<input placeholder=\"Ton nom\" type=\"text\">"], "x": ["<input type=\"text\" value=\"Ton nom\">", "<input type=\"text\" hint=\"Ton nom\">"], "h": "Un texte qui « tient la place »", "e": "`placeholder` disparaît dès qu'on tape. `value` serait un vrai contenu à effacer. Ne remplace pas un `<label>`."},
{"id": "HT-60", "lang": "html", "d": 3, "q": "Écrire l'entité HTML qui affiche le symbole <", "a": ["&lt;"], "x": ["&lessthan;", "<lt>"], "h": "& + l'abréviation de less than + ;", "e": "`&lt;` affiche < sans ouvrir de balise. De même `&gt;` pour > et `&amp;` pour &."}
];
